cd /workspace && node -e "
const XLSX = require('xlsx');
const filePath = '/workspace/testbed/data/order_summary.xlsx';
const wb = XLSX.readFile(filePath);
const ws = wb.Sheets['Orders'];
const data = XLSX.utils.sheet_to_json(ws);

const order = data.find(r => r['Order ID'] === 'ORD-6C71B1');
if (order) {
  order['Status'] = 'confirmed';
  const newWs = XLSX.utils.json_to_sheet(data);
  wb.Sheets['Orders'] = newWs;
  XLSX.writeFile(wb, filePath);
  console.log('Updated ORD-6C71B1 status to confirmed.');
} else {
  console.log('Order not found.');
}

// Verify
const wb2 = XLSX.readFile(filePath);
const verified = XLSX.utils.sheet_to_json(wb2.Sheets['Orders']);
const row = verified.find(r => r['Order ID'] === 'ORD-6C71B1');
console.log('Verification:', row);
"
